      if (data.choices && data.choices[0].message.reasoning_content) {
        console.log("Reasoning content:", data.choices[0].message.reasoning_content);
      }
    }
  } catch (e) {
    console.log("Error connecting to server:", e.message);
  }
}, { timeout: 30000 });

